import {operationDate,currentTimeZone,setTimeZone,validTimeZone} from './time.mjs';
import {escapeHtml as esc,DEMO_DATE,id} from './core.mjs';
import {healthState,RECIPES,DAYS,saveHealthItem,removeHealthItem,toggleHealthItem,toggleGrocery,saveProfessional,groceryList,filterRecipes,consultationSummary} from './health-core.mjs';

// Browser-local demonstration only. No health network, notification or sharing APIs.
export function createHealthUI({getState,setState,save,toast,render,modal,closeModal,button,link,icon,heading,getRoute,download}) {
 const copy=(demo,live)=>globalThis.mentraProduction?live:demo;
 let pending=null,filters={minutes:'all',budget:'all',preference:'all',exclude:''};
 const h=()=>healthState(getState());
 const types={consulta:'Consulta',exame:'Exame',retorno:'Retorno'};
 const sleep={bem:'Dormi bem',regular:'Sono regular',pouco:'Dormi pouco'},energy={boa:'Boa',media:'Média',baixa:'Baixa'};
 const field=(label,name,value='',type='text',attrs='')=>`<label class="health-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
 const area=(label,name,value='',attrs='')=>`<label class="health-field">${label}<textarea name="${name}" rows="3" ${attrs}>${esc(value)}</textarea></label>`;
 const select=(label,name,values,value)=>`<label class="health-field">${label}<select name="${name}">${Object.entries(values).map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
 const error=(inModal=false)=>`<p id="${inModal?'health-modal-error':'health-error'}" class="form-error" role="alert" tabindex="-1"></p>`;
 const date=s=>s?String(s).split('-').reverse().join('/'):'Sem data';
 const tiny=(s)=>`<p class="health-note">${s}</p>`;
 const formFoot=()=>`${error(true)}<p class="health-note">${copy('Somente exemplos fictícios. Fica neste navegador; não envia alertas.','Os registros são sincronizados na sua conta; não enviam alertas externos.')}</p><div class="modal-actions">${button('Cancelar','close-modal','outline')}<button class="primary" type="submit">${copy('Salvar exemplo','Salvar registro')}</button></div>`;
 function fail(messages){const el=document.querySelector('#health-modal-error')||document.querySelector('#health-error');const text=messages?.join(' ')||'Não foi possível guardar este exemplo.';if(el){el.textContent=text;el.focus?.();}toast(text);}
 function commit(result,{close=false,message=copy('Exemplo salvo neste navegador.','Alteração preparada para sincronização.'),focus=''}={}){if(!result.ok){fail(result.errors);return false;}const old=getState();setState(result.state);if(!save()){setState(old);fail(['Não foi possível salvar. Os dados anteriores foram preservados; tente novamente.']);return false;}if(close)closeModal();render();if(close&&!focus)focus='#main-content';if(focus)document.querySelector(focus)?.focus?.({preventScroll:true});toast(message);return true;}
 function renderHomeCard(){return `<section class="home-health" aria-labelledby="home-health-title"><div class="home-health-symbol" aria-hidden="true">${icon('life')}</div><div class="home-health-copy"><span class="eyebrow">SAÚDE E BEM-ESTAR · NOVO</span><h2 id="home-health-title">Como você está hoje?</h2><p>Você lembra de tudo.<br><strong>Quem te lembra de cuidar de você?</strong></p><span class="home-health-caption">Seu cuidado, sua alimentação e seu movimento. Sem virar cobrança.</span></div><div class="home-health-actions">${link('Abrir meu cuidado '+icon('arrow'),'saude/cuidado','primary')}${link('Alimentação e movimento','saude/alimentacao','text-link')}<small>${copy('Demonstração · use dados fictícios','Organização pessoal · dados da sua conta')}</small></div></section>`;}
 function rowActions(collection,item){return `<div class="health-row-actions">${button(item.done?icon('check')+' Feito':'Marcar feito','health-toggle','outline',`data-collection="${collection}" data-id="${esc(item.id)}" aria-pressed="${!!item.done}" aria-label="${item.done?'Reabrir':'Marcar feito'}: ${esc(item.title)}"`)}${button(icon('edit'),'health-edit','icon-button',`data-collection="${collection}" data-id="${esc(item.id)}" aria-label="Editar ${esc(item.title)}"`)}</div>`;}
 function items(collection){const data=h();return data[collection].length?`<ul class="health-item-list">${[...data[collection]].sort((a,b)=>`${a.date||''} ${a.time}`.localeCompare(`${b.date||''} ${b.time}`)).map(item=>`<li class="health-item ${item.done?'is-done':''}"><div class="health-item-copy"><span class="small-label">${collection==='appointments'?esc(types[item.type])+' · ':''}${collection==='medications'?'HORÁRIO INFORMADO · ':date(item.date)+' · '}${esc(item.time)}</span><h3>${esc(item.title)}</h3>${item.note?`<p>${esc(item.note)}</p>`:''}${item.documentId?`<p class="health-doc-ref">${icon('lock')} Referência: ${esc(getState().documents.find(d=>d.id===item.documentId&&!d.trashed)?.title||'Documento indisponível')}</p>`:''}</div>${rowActions(collection,item)}</li>`).join('')}</ul>`:tiny(copy('Nenhum exemplo aqui. Adicione quando quiser.','Nenhum registro aqui. Adicione quando quiser.'));}
 function care(){const data=h();return `<div class="health-care-grid"><section class="health-checkin card"><span class="eyebrow">UM MINUTO PARA VOCÊ</span><h2>Como você está hoje?</h2><p>Registre sono, disposição e o que gostaria de contar na próxima consulta.</p>${button('Fazer meu registro '+icon('plus'),'health-add','primary', 'data-collection="logs"')}<span class="health-note">Sem pontuação, diagnóstico ou cobrança.</span></section><section class="card health-summary-card"><span class="round-icon">${icon('lock')}</span><h2>Seu histórico, nas suas palavras.</h2><p>${data.logs.length} ${data.logs.length===1?'registro disponível':'registros disponíveis'}${copy(' na demonstração. Organize',' na sua conta. Organize')} o que quer levar à consulta.</p>${button('Ver resumo para consulta '+icon('arrow'),'health-summary','outline')}<small>Nada é enviado. Você decide se deseja baixar.</small></section></div><div class="health-columns"><section class="card"><div class="section-head"><div><span class="eyebrow">MEU CUIDADO</span><h2>Consultas, exames e retornos</h2></div>${button(icon('plus'),'health-add','icon-button','data-collection="appointments" aria-label="Adicionar consulta, exame ou retorno"')}</div>${items('appointments')}${tiny(copy('Datas de exemplo. Adicionar aqui não altera sua agenda automaticamente.','Adicionar aqui não altera sua agenda automaticamente.'))}${link('Abrir minha agenda '+icon('arrow'),'vida/agenda','text-link')}</section><section class="card"><div class="section-head"><div><span class="eyebrow">NO HORÁRIO QUE VOCÊ INFORMAR</span><h2>Medicamentos e horários</h2></div>${button(icon('plus'),'health-add','icon-button','data-collection="medications" aria-label="Adicionar horário de medicamento"')}</div>${items('medications')}<div class="health-inline-note">${icon('bell')} <p><b>${copy('Lembrete visual de demonstração.','Horário para consulta no aplicativo.')}</b> Não há aviso no iPhone, push ou alerta com o app fechado. ${copy('As marcações são exemplos, não controle de tratamento.','As marcações são registros manuais, sem verificação de tratamento.')}</p></div>${tiny('Sem doses ou indicação de medicamentos. Organiza apenas o horário informado por você.')}</section></div><section class="card health-history"><div class="section-head"><div><span class="eyebrow">MEU HISTÓRICO</span><h2>Pequenas anotações, sem julgamento.</h2></div>${button('Novo registro','health-add','outline','data-collection="logs"')}</div>${data.logs.length?`<ul class="health-log-list">${[...data.logs].sort((a,b)=>b.date.localeCompare(a.date)).map(log=>`<li><div class="health-log-date">${date(log.date)}</div><div><div class="health-tags"><span>${esc(sleep[log.sleep])}</span><span>Disposição ${esc(energy[log.energy]).toLowerCase()}</span></div><h3>${esc(log.feeling)}</h3>${log.note?`<p>${esc(log.note)}</p>`:''}</div>${button(icon('edit'),'health-edit','icon-button',`data-collection="logs" data-id="${esc(log.id)}" aria-label="Editar registro de ${date(log.date)}"`)}</li>`).join('')}</ul>`:tiny('Seu histórico pode começar com uma frase. Não é preciso registrar todos os dias.')}</section><div class="health-integration"><span>${icon('lock')}</span><div><h3>Exames no lugar certo</h3><p>Você pode referenciar um documento da biblioteca ao organizar uma consulta. ${copy('A biblioteca continua sendo local e demonstrativa; não envie exames reais.','A biblioteca é privada da sua conta; apenas você escolhe o documento de referência.')}</p>${link('Abrir documentos '+icon('arrow'),'vida/documentos','text-link')}</div></div>`;}
 function recipeCards(){const recipes=filterRecipes(filters);return recipes.length?`<div class="health-recipes">${recipes.map(r=>`<article class="health-recipe"><div class="health-recipe-art" aria-hidden="true">${icon(r.preference==='vegetariano'?'leaf':'coffee')}</div><span class="small-label">${r.minutes} MIN · ${r.budget==='economico'?'ECONÔMICO':'CUSTO MODERADO'}</span><h3>${esc(r.title)}</h3><p>${r.preference==='vegetariano'?'Exemplo vegetariano':'Exemplo variado'}</p>${button('Ver receita e escolher '+icon('arrow'),'health-recipe','text-link',`data-id="${r.id}"`)}</article>`).join('')}</div>`:tiny('Nenhum exemplo combina com esses filtros. Ajuste as opções; não há geração automática de receitas.');}
 function food(){const data=h(),groceries=groceryList(data);return `<section class="health-section-intro"><span class="round-icon">${icon('leaf')}</span><div><h2>Comer melhor começa na organização.</h2><p>Escolha refeições possíveis para sua semana. Estes exemplos não são um plano alimentar nem uma indicação nutricional.</p></div></section><section class="card"><div class="section-head"><div><span class="eyebrow">IDEIAS PRÁTICAS · CATÁLOGO DE EXEMPLO</span><h2>O que cabe no seu dia?</h2></div></div><form id="health-filter-form" class="health-filter-form">${select('Tempo disponível','minutes',{'all':'Qualquer tempo','15':'Até 15 min','30':'Até 30 min','45':'Até 45 min'},filters.minutes)}${select('Orçamento ilustrativo','budget',{'all':'Qualquer orçamento',economico:'Econômico',moderado:'Moderado'},filters.budget)}${select('Preferência','preference',{'all':'Todas',vegetariano:'Vegetariano',variado:'Variado'},filters.preference)}${field('Ingredientes que prefere evitar','exclude',filters.exclude,'text','maxlength="150" placeholder="Ex.: ovo, tomate"')}<button type="submit" class="outline">Filtrar ideias</button></form><p class="health-note">O filtro procura palavras nos ingredientes. Não verifica alergias, contaminação cruzada ou adequação clínica. Confira ingredientes e orientações do seu profissional.</p>${recipeCards()}</section><section class="card health-week"><div class="section-head"><div><span class="eyebrow">${copy('SEMANA DEMONSTRATIVA · 12–18 OUT','MODELO SEMANAL · SEGUNDA A DOMINGO')}</span><h2>Seu planejamento da semana</h2></div></div><div class="health-week-grid">${DAYS.map(day=>`<article class="health-day"><h3>${esc(day.label)}</h3>${['almoco','jantar'].map(slot=>{const meal=data.meals.find(m=>m.day===day.id&&m.slot===slot),r=RECIPES.find(r=>r.id===meal?.recipeId);return `<div class="health-meal"><span>${slot==='almoco'?'Almoço':'Jantar'}</span><b>${r?esc(r.title):'Ainda em aberto'}</b>${button(r?'Trocar':'Escolher','health-meal','text-link',`data-day="${day.id}" data-slot="${slot}" aria-label="${r?'Trocar':'Escolher'} ${slot==='almoco'?'almoço':'jantar'} de ${esc(day.label)}"`)}${meal?button('Retirar','health-remove','text-link',`data-collection="meals" data-id="${esc(meal.id)}" aria-label="Retirar ${slot==='almoco'?'almoço':'jantar'} de ${esc(day.label)}"`):''}</div>`;}).join('')}</article>`).join('')}</div></section><div class="health-columns"><section class="card"><div class="section-head"><div><span class="eyebrow">DAS REFEIÇÕES PARA A LISTA</span><h2>Compras, sem esquecer o básico</h2></div></div>${groceries.length?`<ul class="health-grocery">${groceries.map(ingredient=>`<li>${button(`${data.groceryChecked.includes(ingredient)?icon('check'):'<span class="health-empty-check"></span>'}<span>${esc(ingredient)}</span>`,'health-grocery','health-grocery-button',`data-ingredient="${esc(ingredient)}" role="checkbox" aria-checked="${data.groceryChecked.includes(ingredient)}"`)}</li>`).join('')}</ul>`:tiny('Escolha uma refeição acima para montar sua lista.')}<p class="health-note">Derivada das refeições escolhidas. Quantidades e compras ficam por sua conta; não há pedido ou gasto automático.</p></section>${professional('nutrition','Seu plano alimentar, organizado.',copy('Guarde uma anotação fictícia para organizar o plano entregue pelo nutricionista. A Mentra não cria nem altera uma prescrição.','Guarde uma anotação para organizar o plano entregue pelo nutricionista. A Mentra não cria nem altera uma prescrição.'))}</div>`;}
 function professional(kind,title,desc){return `<section class="card health-professional"><span class="eyebrow">ORIENTAÇÃO DO SEU PROFISSIONAL</span><h2>${title}</h2><p>${desc}</p><form id="health-professional-form" data-kind="${kind}">${area(copy('Anotação de exemplo','Anotação pessoal'),'text',h().professional[kind],'maxlength="1500" placeholder="Ex.: consultar o plano entregue pelo profissional na pasta de documentos."')}<button class="outline" type="submit">Guardar anotação</button></form>${link('Abrir documentos '+icon('arrow'),'vida/documentos','text-link')}</section>`;}
 function movement(){const data=h(),done=data.activities.filter(x=>x.done).length;return `<section class="health-movement-hero"><div><span class="eyebrow">MOVIMENTO · NO SEU RITMO</span><h2>Um espaço na agenda.<br><em>Não uma cobrança a mais.</em></h2><p>Organize a atividade que você já escolheu ou o treino orientado pelo seu profissional. Sem metas impostas, intensidade ou treino gerado.</p>${button('Reservar meu momento '+icon('plus'),'health-add','primary','data-collection="activities"')}</div><aside><span>${done}<small> / ${data.activities.length}</small></span><p>${done?'momentos marcados como feitos':'cada começo tem seu tempo'}</p><small>${copy('Na demonstração · sem sequências ou penalidades','Sem sequências ou penalidades')}</small></aside></section><div class="health-columns"><section class="card"><div class="section-head"><h2>Meus momentos de movimento</h2>${button(icon('plus'),'health-add','icon-button','data-collection="activities" aria-label="Adicionar atividade escolhida por mim"')}</div>${items('activities')}${tiny('Atividades escolhidas por você. Datas ficam aqui; não são inseridas automaticamente na agenda.')}${link('Abrir minha agenda '+icon('arrow'),'vida/agenda','text-link')}</section>${professional('movement','Seu treino, do seu jeito de organizar.',copy('Use este espaço para uma referência fictícia ao treino recebido. A Mentra não avalia condição física nem prescreve exercícios.','Use este espaço para uma referência ao treino recebido. A Mentra não avalia condição física nem prescreve exercícios.'))}</div>`;}
 function renderPage(){const part=getRoute().split('/')[1]||'cuidado',tab=['cuidado','alimentacao','movimento'].includes(part)?part:'cuidado';return `<div class="health-page">${heading('SAÚDE E BEM-ESTAR','Cuidar de você também cabe aqui.','Você lembra de tudo. Quem te lembra de cuidar de você?')}<div class="health-privacy">${icon('shield')}<p><b>${copy('Demonstração: use somente dados fictícios.','Registros privados da sua conta.')}</b> ${copy('Os exemplos ficam neste navegador, sem envio ou sincronização.','Os registros são sincronizados com sua conta. Não são enviados automaticamente à IA ou a profissionais.')} ${copy('Não é prontuário seguro, diagnóstico ou prescrição.','Não é prontuário clínico, diagnóstico ou prescrição.')} Não substitui acompanhamento profissional.</p></div><nav class="health-tabs" aria-label="Áreas de saúde e bem-estar">${[['cuidado','life','Meu cuidado'],['alimentacao','leaf','Alimentação'],['movimento','path','Movimento']].map(([key,i,label])=>`<a class="${tab===key?'active':''}" href="#/saude/${key}" ${tab===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('')}</nav>${h().readOnly?`<div class="notice warm" role="alert">${esc(h().error||'Os dados locais de saúde precisam de revisão; foram preservados sem alterações.')}</div>`:''}${error()}${tab==='cuidado'?care():tab==='alimentacao'?food():movement()}<p class="health-footer-note">Integrações automáticas com agenda, finanças e serviços de saúde: planejadas, não conectadas. ${copy('Nenhum dado desta área é enviado a terceiros pelo protótipo.','A sincronização da conta inclui estes registros. Não há envio automático para profissionais.')}</p></div>`;}
 function edit(collection,item){if(!['appointments','medications','logs','activities'].includes(collection))return;const data=item||{},itemId=item?.id||id();let body='';
 if(collection==='logs')body=field(copy('Data do registro fictício','Data do registro'),'date',data.date||operationDate(),'date','required')+select('Como foi seu sono?','sleep',sleep,data.sleep||'regular')+select('Como está sua disposição?','energy',energy,data.energy||'media')+field('Como está se sentindo?','feeling',data.feeling||'','text','required maxlength="160" placeholder="Ex.: tranquila, com vontade de descansar"')+area('Observação para conversar na consulta (opcional)','note',data.note||'','maxlength="1000"');
 else {if(collection==='appointments')body+=select('Tipo de compromisso','type',types,data.type||'consulta');body+=field(collection==='medications'?copy('Nome fictício do medicamento','Nome informado do medicamento'):collection==='activities'?'Atividade escolhida por você':copy('Nome do compromisso fictício','Nome do compromisso'),'title',data.title||'','text','required maxlength="120" placeholder="'+(collection==='medications'?copy('Ex.: Medicamento Exemplo B','Nome conforme informado por você'):collection==='activities'?'Ex.: passeio que escolhi fazer':copy('Ex.: consulta de exemplo','Ex.: retorno agendado'))+'"');if(collection!=='medications')body+=field('Data escolhida','date',data.date||operationDate(),'date','required');body+=field(collection==='medications'?'Horário informado por você':'Horário escolhido','time',data.time||'09:00','time','required');body+=area(collection==='medications'?'Observação de organização (sem doses)':copy('Observação de exemplo (opcional)','Observação (opcional)'),'note',data.note||'','maxlength="1000"');if(collection==='appointments')body+=select(copy('Referência de documento local (opcional)','Referência de documento da conta (opcional)'),'documentId',Object.fromEntries([['','Sem documento'],...getState().documents.filter(d=>!d.trashed).map(d=>[d.id,d.title])]),data.documentId||'');}
 const titles={appointments:'Organizar meu cuidado',medications:'Organizar um horário',logs:'Como você está hoje?',activities:'Reservar um momento para mim'};modal(titles[collection],`<form id="health-item-form" data-collection="${collection}" data-id="${esc(itemId)}">${body}${formFoot()}${item?button(copy('Excluir este exemplo','Excluir este registro'),'health-request-remove','health-delete',`data-collection="${collection}" data-id="${esc(item.id)}"`):''}</form>`);pending={collection,id:itemId};
 }
 function chooseMeal({day='seg',slot='almoco',recipeId=''}={}){const existing=h().meals.find(m=>m.day===day&&m.slot===slot),itemId=id();modal(copy('Escolher uma refeição de exemplo','Escolher uma refeição'),`<form id="health-item-form" data-collection="meals" data-id="${esc(itemId)}">${select('Dia da semana','day',Object.fromEntries(DAYS.map(d=>[d.id,d.label])),day)}${select('Refeição','slot',{almoco:'Almoço',jantar:'Jantar'},slot)}${select('Receita ilustrativa','recipeId',Object.fromEntries(RECIPES.map(r=>[r.id,r.title])),recipeId||existing?.recipeId||RECIPES[0].id)}<p class="health-note">Escolher substitui apenas a refeição desse dia e horário. A lista de compras acompanha sua escolha.</p>${formFoot()}</form>`);pending={collection:'meals',id:itemId};}
 function showRecipe(recipe){modal(esc(recipe.title),`<div class="health-recipe-detail"><span class="badge">${recipe.minutes} min · tempo aproximado</span><h3>Ingredientes ilustrativos</h3><ul>${recipe.ingredients.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Ideia de preparo</h3><ol>${recipe.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="health-note">${recipe.allergens.length?'Ingredientes que pedem atenção: '+esc(recipe.allergens.join(', '))+'. ':''}Não é avaliação de alergias ou recomendação individual. Confira ingredientes, rótulos e orientações profissionais.</p></div><div class="modal-actions">${button('Fechar','close-modal','outline')}${button('Escolher para a semana','health-choose-recipe','primary',`data-id="${recipe.id}"`)}</div>`);}
 function handleClick(action,data={}){if(!action.startsWith('health-'))return false;const current=h(),collection=data.collection,item=current[collection]?.find?.(x=>x.id===data.id);
 if(action==='health-add')edit(collection);
 else if(action==='health-edit'&&item)edit(collection,item);
 else if(action==='health-toggle'&&item)commit(toggleHealthItem(getState(),collection,item.id),{message:item.done?'Exemplo reaberto. No seu ritmo.':'Feito registrado na demonstração.',focus:`[data-action="health-toggle"][data-id="${item.id}"]`});
 else if(action==='health-request-remove'&&item){modal('Excluir este exemplo?',`<p>Somente este registro de demonstração será removido deste navegador.</p><div class="modal-actions">${button('Cancelar','close-modal','outline')}${button('Excluir exemplo','health-remove-confirm','primary',`data-collection="${collection}" data-id="${esc(item.id)}"`)}</div>`);pending={remove:true,collection,id:item.id};}
 else if(action==='health-remove-confirm'&&pending?.remove&&pending.collection===collection&&pending.id===data.id)commit(removeHealthItem(getState(),collection,data.id),{close:true,message:copy('Exemplo removido.','Registro removido.')});
 else if(action==='health-remove'&&collection==='meals'&&item)commit(removeHealthItem(getState(),collection,data.id),{message:'Refeição retirada. Lista de compras atualizada.'});
 else if(action==='health-grocery')commit(toggleGrocery(getState(),data.ingredient),{message:'Lista de compras atualizada.',focus:`[data-action="health-grocery"][data-ingredient="${String(data.ingredient).replace(/["\\]/g,'\\$&')}"]`});
 else if(action==='health-meal')chooseMeal(data);
 else if(action==='health-recipe'){const r=RECIPES.find(r=>r.id===data.id);if(r)showRecipe(r);}
 else if(action==='health-choose-recipe'&&RECIPES.some(r=>r.id===data.id))chooseMeal({recipeId:data.id});
 else if(action==='health-summary')modal('Resumo para a consulta · exemplo',`<p class="health-note">Gerado dos registros deste navegador, sem interpretação clínica. Revise antes de baixar. Nenhum envio é feito.</p><pre class="health-summary-text">${esc(consultationSummary(getState()))}</pre><div class="modal-actions">${button('Fechar','close-modal','outline')}${button('Baixar resumo em texto '+icon('down'),'health-download-summary','primary')}</div>`);
 else if(action==='health-download-summary'){download('mentra-resumo-ficticio-consulta.txt',consultationSummary(getState()),'text/plain;charset=utf-8');toast('Download solicitado. O resumo não foi enviado a ninguém.');}
 return true;}
 function handleSubmit(form){if(!form.id.startsWith('health-'))return false;if(!form.checkValidity()){form.reportValidity();return true;}const raw=Object.fromEntries(new FormData(form));if(form.id==='health-filter-form'){filters={minutes:raw.minutes||'all',budget:raw.budget||'all',preference:raw.preference||'all',exclude:raw.exclude||''};render();document.querySelector('#health-filter-form button')?.focus?.();}
 else if(form.id==='health-item-form'){if(!pending||pending.remove||pending.collection!==form.dataset.collection||pending.id!==form.dataset.id)return true;commit(saveHealthItem(getState(),pending.collection,raw,pending.id),{close:true});}
 else if(form.id==='health-professional-form')commit(saveProfessional(getState(),form.dataset.kind,raw.text||''));return true;}
 return {renderPage,renderHomeCard,handleClick,handleSubmit,cancelPending:()=>{pending=null;},routeChanged:()=>{pending=null;}};
}
